Lau sạch chậu trước khi sử dụng. Kiểm tra lỗ thoát nước, cạnh miệng và đường kính bầu cây để chọn kích thước phù hợp; không dùng vật cứng chà lên bề mặt men.

## Lưu ý trước khi chọn
Đối chiếu mô tả, kích thước và tình trạng của chậu đất nung cho sen đá. Đây là dữ liệu minh họa cho môi trường phát triển; ảnh thư viện không xác nhận một cây cụ thể của người bán thực.','120000','9',NULL,'ACTIVE','{}','{"developmentDemo":true,"seed":"storefront-v1","imageSource":null}' FROM storefront_seed_owners d JOIN users u ON u.email=d.email JOIN stores s ON s.owner_user_id=u.id JOIN categories c ON c.slug='chau-va-phu-kien' AND c.is_active=TRUE WHERE d.shop_key='nha-chau' AND NOT EXISTS (SELECT 1 FROM products WHERE slug='demo-storefront-nha-chau-7');
DROP TEMPORARY TABLE storefront_seed_owners;


-- Dữ liệu demo bổ sung; chỉ chèn mới, giữ dữ liệu đã chỉnh sửa.
-- Thảo luận demo chỉ được chèn mới; các tác giả phụ dùng BCrypt demo.
-- Chỉ dùng danh tính chưa tồn tại, không nhận tài khoản đang có làm tài khoản demo.
CREATE TEMPORARY TABLE discussion_seed_authors (email VARCHAR(255) PRIMARY KEY, display_name VARCHAR(150));
INSERT INTO discussion_seed_authors SELECT 'discussion-v1-lan@bonsai.market','Lan · Demo' WHERE NOT EXISTS (SELECT 1 FROM users WHERE email='discussion-v1-lan@bonsai.market');
INSERT INTO discussion_seed_authors SELECT 'discussion-v1-minh@bonsai.market','Minh · Demo' WHERE NOT EXISTS (SELECT 1 FROM users WHERE email='discussion-v1-minh@bonsai.market');
INSERT INTO discussion_seed_authors SELECT 'discussion-v1-an@bonsai.market','An · Demo' WHERE NOT EXISTS (SELECT 1 FROM users WHERE email='discussion-v1-an@bonsai.market');
INSERT INTO users(name,email,password_hash,role,is_active,email_verified_at)
SELECT display_name,email,'${devSeedPasswordHash}','CUSTOMER',TRUE,CURRENT_TIMESTAMP(6) FROM discussion_seed_authors;

INSERT INTO community_posts(author_id,title,body,topic,seed_key)
SELECT u.id,'Quan sát giá thể sen đá trước khi tưới','Mình đặt sen đá ở ban công có mái che. Thay vì tưới theo ngày cố định, mình quan sát độ khô và độ thoáng của giá thể.\n\nCác bạn thường ghi lại những dấu hiệu nào để điều chỉnh cách chăm cây? Đây là cuộc thảo luận minh họa trong môi trường phát triển.','SUCCULENTS','discussion-v1-succulents'
FROM users u JOIN discussion_seed_authors a ON a.email=u.email WHERE u.email='discussion-v1-lan@bonsai.market' AND NOT EXISTS(SELECT 1 FROM community_posts WHERE seed_key='discussion-v1-succulents');
INSERT INTO community_posts(author_id,title,body,topic,seed_key)
SELECT u.id,'Chọn vị trí ngắm một dáng bonsai nhỏ','Mình đang sắp xếp lại kệ bonsai và thấy khoảng trống quanh cây ảnh hưởng nhiều đến cách nhìn đường thân.\n\nBạn thích đặt cây ngang tầm mắt hay thấp hơn một chút? Bài viết minh họa để trao đổi về bố cục, không khẳng định một thế cây cụ thể.','BONSAI','discussion-v1-bonsai'
FROM users u JOIN discussion_seed_authors a ON a.email=u.email WHERE u.email='discussion-v1-minh@bonsai.market' AND NOT EXISTS(SELECT 1 FROM community_posts WHERE seed_key='discussion-v1-bonsai');
INSERT INTO community_posts(author_id,title,body,topic,seed_key)
SELECT u.id,'Ghi chép thay đổi của góc vườn qua mùa','Mình chụp cùng một góc vườn vào đầu mỗi tháng để so sánh ánh sáng và màu lá. Những ghi chú nhỏ giúp mình nhớ được thay đổi sau khi chuyển chậu.\n\nCác bạn có cách ghi chép đơn giản nào muốn chia sẻ? Đây là nội dung phát triển, không phải bài của thành viên thật.','CARE','discussion-v1-care'
FROM users u JOIN discussion_seed_authors a ON a.email=u.email WHERE u.email='discussion-v1-an@bonsai.market' AND NOT EXISTS(SELECT 1 FROM community_posts WHERE seed_key='discussion-v1-care');
INSERT INTO community_posts(author_id,title,body,topic,seed_key)
SELECT u.id,'Một chiếc kệ nhỏ cho những chậu cây mới','Mình muốn chừa khoảng cách giữa các chậu để dễ quan sát và vệ sinh kệ. Đang cân nhắc cách sắp xếp sao cho cây nào cũng có ánh sáng phù hợp.\n\nBài chia sẻ minh họa dành cho môi trường phát triển.','OTHER','discussion-v1-shelf'
FROM users u JOIN discussion_seed_authors a ON a.email=u.email WHERE u.email='discussion-v1-lan@bonsai.market' AND NOT EXISTS(SELECT 1 FROM community_posts WHERE seed_key='discussion-v1-shelf');

INSERT INTO community_comments(post_id,author_id,body,seed_key)
SELECT p.id,u.id,'Mình thường ghi thêm vị trí đặt cây và thời tiết hôm đó, nhờ vậy dễ đối chiếu hơn khi lá có thay đổi.','discussion-v1-comment-care'
FROM community_posts p JOIN users u ON u.email='discussion-v1-minh@bonsai.market' JOIN discussion_seed_authors a ON a.email=u.email WHERE p.seed_key='discussion-v1-care' AND NOT EXISTS(SELECT 1 FROM community_comments WHERE seed_key='discussion-v1-comment-care');
INSERT INTO community_comments(post_id,author_id,body,seed_key)
SELECT p.id,u.id,'Mình còn nhìn các lỗ thoát nước dưới đáy chậu. Cùng một loại giá thể nhưng mỗi vị trí trồng lại khô khác nhau.','discussion-v1-comment-succulents'
FROM community_posts p JOIN users u ON u.email='discussion-v1-an@bonsai.market' JOIN discussion_seed_authors a ON a.email=u.email WHERE p.seed_key='discussion-v1-succulents' AND NOT EXISTS(SELECT 1 FROM community_comments WHERE seed_key='discussion-v1-comment-succulents');

-- Câu trả lời chính thức chỉ thuộc chủ gian hàng của đúng sản phẩm demo.
INSERT INTO product_questions(product_id,author_id,body,answer_author_id,answer_body,answered_at,seed_key)
SELECT p.id,u.id,'Mẫu sen đá này có kèm chậu đang được mô tả không?',s.owner_user_id,'Mẫu minh họa này gồm cây và chậu đất nung như nội dung sản phẩm.',CURRENT_TIMESTAMP(6),'discussion-v1-question-succulent-answered'
FROM products p JOIN stores s ON s.id=p.store_id JOIN users owner ON owner.id=s.owner_user_id JOIN users u ON u.email='discussion-v1-lan@bonsai.market' JOIN discussion_seed_authors a ON a.email=u.email
WHERE p.slug='demo-storefront-vuon-hien-2' AND p.status='ACTIVE' AND s.status='ACTIVE' AND owner.email='storefront-v1-vuon-hien@bonsai.market' AND owner.password_hash='${devSeedPasswordHash}' AND NOT EXISTS(SELECT 1 FROM product_questions WHERE seed_key='discussion-v1-question-succulent-answered');
INSERT INTO product_questions(product_id,author_id,body,seed_key)
SELECT p.id,u.id,'Mình có thể xem thêm thông tin đường kính chậu của mẫu này không?','discussion-v1-question-succulent-open'
FROM products p JOIN stores s ON s.id=p.store_id JOIN users owner ON owner.id=s.owner_user_id JOIN users u ON u.email='discussion-v1-minh@bonsai.market' JOIN discussion_seed_authors a ON a.email=u.email
WHERE p.slug='demo-storefront-vuon-hien-2' AND p.status='ACTIVE' AND s.status='ACTIVE' AND owner.email='storefront-v1-vuon-hien@bonsai.market' AND owner.password_hash='${devSeedPasswordHash}' AND NOT EXISTS(SELECT 1 FROM product_questions WHERE seed_key='discussion-v1-question-succulent-open');
INSERT INTO product_questions(product_id,author_id,body,answer_author_id,answer_body,answered_at,seed_key)
SELECT p.id,u.id,'Chiều cao bonsai được tính từ mặt chậu hay gồm cả chậu?',s.owner_user_id,'Thông số trong mẫu minh họa được tính từ mặt giá thể đến ngọn cây.',CURRENT_TIMESTAMP(6),'discussion-v1-question-bonsai-answered'
FROM products p JOIN stores s ON s.id=p.store_id JOIN users owner ON owner.id=s.owner_user_id JOIN users u ON u.email='discussion-v1-an@bonsai.market' JOIN discussion_seed_authors a ON a.email=u.email
WHERE p.slug='demo-storefront-moc-vien-1' AND p.status='ACTIVE' AND s.status='ACTIVE' AND owner.email='storefront-v1-moc-vien@bonsai.market' AND owner.password_hash='${devSeedPasswordHash}' AND NOT EXISTS(SELECT 1 FROM product_questions WHERE seed_key='discussion-v1-question-bonsai-answered');
INSERT INTO product_questions(product_id,author_id,body,seed_key)
SELECT p.id,u.id,'Dáng cây trong mô tả phù hợp để nhìn từ phía nào?','discussion-v1-question-bonsai-open'
FROM products p JOIN stores s ON s.id=p.store_id JOIN users owner ON owner.id=s.owner_user_id JOIN users u ON u.email='discussion-v1-lan@bonsai.market' JOIN discussion_seed_authors a ON a.email=u.email
WHERE p.slug='demo-storefront-moc-vien-2' AND p.status='ACTIVE' AND s.status='ACTIVE' AND owner.email='storefront-v1-moc-vien@bonsai.market' AND owner.password_hash='${devSeedPasswordHash}' AND NOT EXISTS(SELECT 1 FROM product_questions WHERE seed_key='discussion-v1-question-bonsai-open');
DROP TEMPORARY TABLE discussion_seed_authors;

-- Minh họa COD cho đơn demo đang chờ. Đây là snapshot demo, không phải báo phí/vận đơn của hãng.
-- Quote hết hạn và shop_id=0; cấu hình GHN/COD mặc định tắt, không được dùng để tạo vận đơn thật.
INSERT INTO shipping_parcels(order_id,weight_grams,length_cm,width_cm,height_cm,carrier_accepted_goods,revision,updated_at)
SELECT o.id,1000,30,25,40,FALSE,0,CURRENT_TIMESTAMP(6)
FROM orders o JOIN users u ON u.id=o.buyer_user_id
WHERE o.code='BSM-DEV-010' AND u.email='user@bonsai.market' AND u.password_hash='${devSeedPasswordHash}'
AND u.bio='Tài khoản demo phát triển; không phải người dùng thật'
AND NOT EXISTS(SELECT 1 FROM shipping_parcels p WHERE p.order_id=o.id);

INSERT INTO shipping_quotes(id,order_id,buyer_id,shop_id,parcel_revision,service_type,service_name,fee,order_fingerprint,destination_snapshot,pickup_snapshot,parcel_snapshot,expires_at,created_at,selected_at)
SELECT '00000000-0000-4000-8000-000000000010',o.id,o.buyer_user_id,0,0,2,'Phí vận chuyển demo; không phải GHN',o.shipping_fee,'demo-only',o.shipping_address_snapshot,'{}',
'{"weightGrams":1000,"lengthCm":30,"widthCm":25,"heightCm":40}','2000-01-01 00:00:00',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)
FROM orders o JOIN users u ON u.id=o.buyer_user_id JOIN shipping_parcels p ON p.order_id=o.id
WHERE o.code='BSM-DEV-010' AND u.email='user@bonsai.market' AND u.password_hash='${devSeedPasswordHash}'
AND u.bio='Tài khoản demo phát triển; không phải người dùng thật'
AND NOT EXISTS(SELECT 1 FROM shipping_quotes q WHERE q.id='00000000-0000-4000-8000-000000000010');

INSERT INTO order_payments(order_id,quote_id,method,status,currency,amount_due,cod_amount,shipping_fee,fee_payer,collection_status,settlement_status,store_name_snapshot,created_at)
SELECT o.id,q.id,'COD','AWAITING_COLLECTION','VND',o.total,o.subtotal,o.shipping_fee,2,'REQUESTED','UNKNOWN',s.name,CURRENT_TIMESTAMP(6)
FROM orders o JOIN users u ON u.id=o.buyer_user_id JOIN stores s ON s.id=o.store_id
JOIN shipping_quotes q ON q.order_id=o.id AND q.id='00000000-0000-4000-8000-000000000010'
WHERE o.code='BSM-DEV-010' AND o.status='PENDING' AND u.email='user@bonsai.market' AND u.password_hash='${devSeedPasswordHash}'
AND u.bio='Tài khoản demo phát triển; không phải người dùng thật'
AND NOT EXISTS(SELECT 1 FROM order_payments p WHERE p.order_id=o.id);

-- Tồn kho trong seed là tồn khả dụng. Ledger chỉ ghi phần đã trừ cho đơn demo, không trừ lại khi replay.
INSERT INTO inventory_debits(order_id,product_id,quantity,restored)
SELECT i.order_id,i.product_id,SUM(i.quantity),FALSE FROM order_items i JOIN orders o ON o.id=i.order_id
JOIN order_payments p ON p.order_id=o.id JOIN users u ON u.id=o.buyer_user_id
WHERE o.code='BSM-DEV-010' AND u.email='user@bonsai.market' AND u.password_hash='${devSeedPasswordHash}'
AND NOT EXISTS(SELECT 1 FROM inventory_debits d WHERE d.order_id=i.order_id AND d.product_id=i.product_id)
GROUP BY i.order_id,i.product_id;

-- Thông báo demo ở trạng thái kết thúc, không thể được dispatcher gửi ra ngoài.
INSERT INTO order_notification_outbox(id,order_id,event_type,recipient,subject,body,dedup_key,status,attempts,next_attempt_at,updated_at,created_at,error_code)
SELECT '00000000-0000-4000-8000-000000000011',o.id,'ORDER_PLACED','user@bonsai.market','[Demo] Đơn hàng đang chờ',
'Dữ liệu minh họa phát triển; không phải thư đã gửi.','demo-seed-order-notification','FAILED',8,CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6),'DEMO_SEED'
FROM orders o JOIN order_payments p ON p.order_id=o.id JOIN users u ON u.id=o.buyer_user_id
WHERE o.code='BSM-DEV-010' AND u.email='user@bonsai.market' AND u.password_hash='${devSeedPasswordHash}'
AND NOT EXISTS(SELECT 1 FROM order_notification_outbox n WHERE n.dedup_key='demo-seed-order-notification');

